select slug, scheme from benchmark_workouts where slug in ('leehan', 'liam', 'locke', 'lorenzo', 'luke', 'maloney', 'manuel', 'marco', 'marston', 'martin', 'matt-16', 'maxim-56', 'maxton') order by slug;
